fn solve(input: Vec<i8>) -> Vec<&'static str> {
    if input.is_empty() {
        return Vec::new();
    }
    let t = input[0] as usize;
    let mut out: Vec<&'static str> = Vec::with_capacity(t);

    for i in 0..t {
        let n = input[i + 1] as i32; // work in wider type for safety
        let winner = winner_for(n);
        out.push(winner);
    }

    out
}

fn winner_for(n: i32) -> &'static str {
    // Rules in order
    if n == 1 {
        return "FastestFinger";
    }
    if n == 2 {
        return "Ashishgup";
    }
    if is_power_of_two(n) {
        return "FastestFinger";
    }
    if n % 4 != 2 {
        return "Ashishgup";
    }

    // n % 4 == 2
    let p = n / 2;
    if is_limited_prime(p) {
        "FastestFinger"
    } else {
        "Ashishgup"
    }
}

fn is_power_of_two(n: i32) -> bool {
    // n is positive per problem statement
    (n & (n - 1)) == 0
}

fn is_limited_prime(p: i32) -> bool {
    if p <= 1 {
        return false;
    }
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    // any odd p > 2 is considered prime under the "limited-prime" definition
    true
}